"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["62469"],{81765(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.no_exigencia.consequencia_incoerente_com_acao_da_vaga","status":422,"titulo":"A consequ\xeancia do grupo \xe9 incoerente com a a\xe7\xe3o de indeferimento da modalidade que ele alcan\xe7a"},"descricao":{"codigo":"uniplus.selecao.no_exigencia.consequencia_incoerente_com_acao_da_vaga","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["Um grupo de alternativas (OU) pode ter consequ\xeancia pr\xf3pria de indeferimento. Quando uma\\nmodalidade de vaga declara o que acontece com o candidato indeferido (a a\xe7\xe3o de indeferimento),\\na consequ\xeancia do grupo tem de ser a mesma. O grupo apontado declara uma consequ\xeancia\\ndiferente da a\xe7\xe3o de uma modalidade que ele pode alcan\xe7ar.","O grupo alcan\xe7a as modalidades que qualquer um dos documentos dele pode alcan\xe7ar pelas\\ncondi\xe7\xf5es. S\xf3 entram na compara\xe7\xe3o as modalidades que declaram a\xe7\xe3o de indeferimento. A grafia\\ndiferente entre os dois vocabul\xe1rios (`RECLASSIFICA_AC` na exig\xeancia e `RECLASSIFICAR_AC` na\\nmodalidade) \xe9 tratada como a mesma a\xe7\xe3o. A mensagem de detalhe indica o grupo e a modalidade\\nem conflito.","A confer\xeancia acontece quando a configura\xe7\xe3o vai ser congelada, na publica\xe7\xe3o ou na retifica\xe7\xe3o em ato \xfanico. Ela vem depois da dos documentos\\nexigidos (ver\\n[`documento_exigido.consequencia_incoerente_com_acao_da_vaga`](/erros/uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga)),\\ne a primeira viola\xe7\xe3o encontrada interrompe a confer\xeancia."],"comoResolver":["Alinhe a consequ\xeancia do grupo \xe0 a\xe7\xe3o de indeferimento da modalidade apontada, ou revise a\\na\xe7\xe3o dessa modalidade, se for ela que est\xe1 errada. Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"No exigencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);